/** QA only: signed exact-Source alternatives, earliest rejection and explicit trust boundary. */
final class ContextUniversalSignedAlternativesMatrix {
    static final class Fixture {
        final Snapshot x,a,b,d,e;final Packet common;final PrivatePool pool;final Map<Cut,PrivatePool> pools;
        Fixture(boolean stable)throws Exception {
            x=bind(true,"!anchor(1); !@u @v a(u,1)&&b(u,v)->r(u,v);");a=bind(false,"!$u a(u,1);");
            b=bind(false,"!@u @v b(u,v); !@u @v r(u,v)&&need(v)->s(u,v); !need(2); !@u @v r(u,v)->r(u,v);"+(stable?" !@u @v ~s(u,v)||~ban(v); !ban(3);":""));
            d=bind(false,"!@u @v b(u,v); !@u @v r(u,v)&&need(v)->s(u,v); !need(2);");e=stable?null:bind(false,"!@u ~s(u,2);");common=ContextPrivateWitnessPoolRunner.common(x);pool=ContextWitnessResultTransport.privatePool(common,x,a,WORK);pools=Collections.singletonMap(pool.cut,pool);require(pool.sources.size()==1&&pool.sources.contains(a.primary.get(0).source),"one actual whole private Origin Source, no fabricated witness");
        }
        Frame frame(List<Snapshot> order){return new Frame(x,order,common,pools);}
        Map<Set<Source>,Integer> fixed(boolean rejection,int base){Map<Set<Source>,Integer> result=new HashMap<>();for(Snapshot donor:Arrays.asList(b,d))for(Snapshot rule:Arrays.asList(b,d))for(Snapshot need:Arrays.asList(b,d))for(boolean loop:new boolean[]{false,true}){Set<Source> s=ContextUniversalSourceAlternativesMatrix.sources(x.primary.get(1).source,a.primary.get(0).source,donor.primary.get(0).source,rule.primary.get(1).source,need.primary.get(2).source);if(loop)s.add(b.primary.get(3).source);if(rejection)s.add(e.primary.get(0).source);require(result.put(s,base+(loop?1:0))==null,"sixteen distinct exact rule/donor/loop Source alternatives");}return result;}
        Map<Set<Source>,Integer> negative(String predicate){Map<Set<Source>,Integer> result=new HashMap<>();if(predicate.equals("ban")){for(Map.Entry<Set<Source>,Integer> e:fixed(false,3).entrySet()){Set<Source> set=new HashSet<>(e.getKey());set.add(b.primary.get(4).source);result.put(set,e.getValue()+1);}}else for(Snapshot donor:Arrays.asList(b,d))for(Snapshot rule:Arrays.asList(b,d))for(boolean loop:new boolean[]{false,true}){Set<Source> set=ContextUniversalSourceAlternativesMatrix.sources(x.primary.get(1).source,a.primary.get(0).source,donor.primary.get(0).source,rule.primary.get(1).source,b.primary.get(4).source,b.primary.get(5).source);if(loop)set.add(b.primary.get(3).source);require(result.put(set,loop?4:3)==null,"eight distinct exact negative-need Source alternatives");}return result;}
        Map<Set<Source>,Integer> early(){Map<Set<Source>,Integer> result=new HashMap<>();for(Snapshot owner:Arrays.asList(b,d))for(boolean loop:new boolean[]{false,true})if(owner==b||!loop){Set<Source> set=ContextUniversalSourceAlternativesMatrix.sources(x.primary.get(1).source,a.primary.get(0).source,owner.primary.get(0).source,owner.primary.get(1).source,owner.primary.get(2).source,e.primary.get(0).source);if(loop)set.add(b.primary.get(3).source);result.put(set,loop?5:4);}return result;}
        void products(Result r){
            Item s=r.output.packet.items.stream().filter(i->i.atom.predicate.equals("s")).findFirst().get();require(s.atom.arguments.size()==2&&s.atom.arguments.get(1).origin==null&&s.atom.arguments.get(1).value.semanticallyEquals(b.primary.get(2).clauses.get(0).literals.get(0).arguments.get(0).value),"fixed s uses actual need2 value, not an arbitrary instance");require(s.atom.positive&&ContextUniversalSourceAlternativesMatrix.supports(s.proofs).equals(fixed(false,3)),"all sixteen signed-stable s Source/grade alternatives including proper supersets");require(ContextUniversalPrivateSymbolicMatrix.origins(r.output.packet,"s").size()==1&&s.atom.arguments.get(0).origin.source.equals(a.primary.get(0).source),"actual rigid original private Origin retained");
            for(String name:new String[]{"need","ban"}){Item item=r.output.packet.items.stream().filter(i->i.atom.predicate.equals(name)).findFirst().get();require(item.atom.arguments.size()==1&&item.atom.arguments.get(0).origin==null&&item.atom.arguments.get(0).value.semanticallyEquals(b.primary.get(name.equals("need")?5:2).clauses.get(0).literals.get(0).arguments.get(0).value),"signed consequence at exact ban3/need2 value");Map<Set<Source>,Integer> actual=ContextUniversalSourceAlternativesMatrix.supports(item.proofs),expected=negative(name);require(!item.atom.positive&&actual.equals(expected)&&actual.size()==(name.equals("need")?8:16),"ALL exact signed "+name+" alternatives/depths retained");for(Set<Source> set:actual.keySet())if(!set.contains(b.primary.get(3).source)){Set<Source> superset=new HashSet<>(set);superset.add(b.primary.get(3).source);require(actual.get(superset)==actual.get(set)+1,"signed proper Source superset retained beside shorter subset");}}
            require(r.output.packet.items.size()==4&&r.output.packet.items.stream().noneMatch(i->i.atom.predicate.equals("a")||i.atom.predicate.equals("b")||i.atom.predicate.equals("r")||(i.atom.positive&&(i.atom.predicate.equals("need")||i.atom.predicate.equals("ban")))),"no raw private/donor/positive foreign disclosure or fabricated fixed r");require(r.symbolicOutput.units.size()==4&&r.compoundOutput.clauses.size()==12,"complete bounded symbolic/compound signed inventory retained");
            PrivatePool out=r.output.privatePools.get(pool.cut);require(out!=null&&out.snapshot==a&&out.sources.equals(pool.sources)&&out.declarations.size()==pool.declarations.size()&&out.local.items.stream().filter(i->i.atom.predicate.equals("a")).count()==1&&ContextUniversalPrivateSymbolicMatrix.origins(out.local,"s").size()==1,"actual original private manifest/local product retained");require(pool.common==common&&ContextUniversalPrivateSymbolicMatrix.origins(pool.local,"s").isEmpty(),"original private input immutable");
        }
    }
    static void stableIndependent()throws Exception {Fixture f=new Fixture(true);Result previous=null;for(List<Snapshot> order:ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(f.a,f.b,f.d))){Frame frame=f.frame(order);Result r=ContextUniversalSeparatePrivateMatrix.continued(frame);f.products(r);require(r.history.stream().anyMatch(row->row.commonChanged&&row.input.items.size()==row.barrier.packet.items.size()),"signed Source/grade-only progress still requires all-cut requalification");if(previous!=null)same(previous,r);previous=r;}System.out.println("SIGNED_ALTERNATIVES_STABLE independentOrders=6 fixedAlternatives=16 negativeNeed=8 negativeBan=16");}
    static void stableTrusted()throws Exception {Fixture f=new Fixture(true);Result independent=ContextUniversalSeparatePrivateMatrix.continued(f.frame(Arrays.asList(f.a,f.b,f.d))),previous=null;for(List<Snapshot> members:Arrays.asList(Arrays.asList(f.b,f.d),Arrays.asList(f.d,f.b))){Snapshot g=ContextProductionNativeBinding.trusted("signed-stable",members,WORK);require(Cut.of(g).members.size()==2,"whole physical trusted donor/rule member inventory");for(List<Snapshot> order:Arrays.asList(Arrays.asList(f.a,g),Arrays.asList(g,f.a))){Result r=ContextUniversalSeparatePrivateMatrix.continued(f.frame(order));f.products(r);same(independent,r);if(previous!=null)same(previous,r);previous=r;}}System.out.println("SIGNED_ALTERNATIVES_TRUSTED stableMemberOrders=2 cutOrders=2 independentSharedAndPrivateEqual=true");}
    static Map<Set<Source>,Integer> empty(Refutation r){List<Support> values=new ArrayList<>();for(org.kanger.ContextUniversalFrozenConstraints.Proof p:r.proofs){require(p.clause==null,"only empty proof roots in sourced rejection");values.add(p.support);}return ContextUniversalSourceAlternativesMatrix.supports(values);}
    static Result rejection(Fixture f,Frame frame,boolean trusted){SessionRun s=run(frame,8,WORK,4096);ContextUniversalContinuationRefutationRunner.reject(frame,s,trusted?1:2);if(trusted){Cut group=frame.cuts.stream().filter(c->c.trustedGroup!=null).map(Cut::of).findFirst().get();require(s.result.refutations.keySet().equals(new HashSet<>(Arrays.asList(f.pool.cut,group))),"only actual private and trusted cuts refute at first barrier");require(empty(s.result.refutations.get(f.pool.cut)).equals(f.fixed(true,4))&&empty(s.result.refutations.get(group)).equals(f.fixed(true,3)),"all sixteen exact rejection Sources, correct DISTINCT per-cut minima4/5 versus3/4");require(f.fixed(true,4).entrySet().containsAll(f.early().entrySet()),"independent earliest proofs are included at same grade in trusted private rejection inventory");}else{require(s.result.refutations.keySet().equals(Collections.singleton(Cut.of(f.e))),"only independent negative-opinion cut rejects on NEXT barrier");require(empty(s.result.refutations.get(Cut.of(f.e))).equals(f.early()),"EXACT three currently available rejection alternatives, no false saturation requirement");}return s.result;}
    static void ordinaryReplay(Fixture f,Frame frame){
        Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> checks=new LinkedHashMap<>();Map<Cut,ContextUniversalGroupedLocalRounds.Certificate> certificates=new LinkedHashMap<>();List<Snapshot> targets=new ArrayList<>();targets.add(null);targets.addAll(frame.cuts);
        for(Snapshot target:targets){Cut cut=target==null?Cut.of(f.x):Cut.of(target);ContextUniversalFrozenConstraints.SessionClosure r=ContextUniversalFrozenConstraints.closeSignedCompoundsWithValidationReuse(ContextUniversalCompoundExchangeRunner.rows(f.x,target),f.common,f.pools.get(cut),frame.units,frame.compounds,16,16,512,256,WORK,4096);require(r.result.closed&&!r.result.xRefuted&&!r.result.foreignRefuted&&r.metrics.entries==0,r.result.reason);ContextUniversalGroupedLocalRounds.Closure local=ContextUniversalGroupedLocalRounds.runWithValidationReuse(r.result,frame.local,4096);require(local.stable&&ContextUniversalGroupedLocalRounds.sameContents(r.result,local.output.output,ContextGroundProductionRounds.budget(WORK)),"certification does not change ANY ordinary proof Source-grade pool");checks.put(cut,local.output.output);certificates.put(cut,local.output);}
        Map<Cut,ConstraintTransfer> transfers=new LinkedHashMap<>();for(Map.Entry<Cut,ContextUniversalGroupedLocalRounds.Certificate> e:certificates.entrySet()){ContextWitnessResultTransport.SessionTransfer t=ContextWitnessResultTransport.transferConstraintsCertifiedWithValidationReuse(e.getValue(),16,WORK,4096);require(t.transfer.transferred&&t.metrics.entries==0,t.transfer.reason);ContextUniversalSignedProductAudit.SessionBinding products=ContextUniversalSignedProductAudit.bindWithValidationReuse(e.getValue().output,t.transfer,65536,WORK,4096);require(products.result.bound&&products.metrics.entries==0,"actual certified Origin transport independently bound to ordinary products");transfers.put(e.getKey(),t.transfer);}ConstraintBarrier first=ContextWitnessResultTransport.mergeConstraints(ContextWitnessResultTransport.family(f.common,new ArrayList<>(checks.keySet()),WORK),transfers,WORK);require(first.merged,first.reason);Item product=first.packet.items.stream().filter(i->i.atom.predicate.equals("s")).findFirst().get();Map<Set<Source>,Integer> actual=ContextUniversalSourceAlternativesMatrix.supports(product.proofs),expected=new HashMap<>();for(Map.Entry<Set<Source>,Integer> e:f.early().entrySet()){Set<Source> set=new HashSet<>(e.getKey());set.remove(f.e.primary.get(0).source);expected.put(set,e.getValue()-1);}require(actual.equals(expected),"independent ordinary FIRST barrier has same three positive Source-grade alternatives before rejection");
        ContextUniversalSignedUnitExchange.SessionCollection units=ContextUniversalSignedUnitExchange.collectWithValidationReuse(f.x,f.common,new ArrayList<>(checks.keySet()),checks,512,256,16,WORK,4096);ContextUniversalCompoundExchange.SessionCollection compounds=ContextUniversalCompoundExchange.collectWithValidationReuse(f.x,f.common,new ArrayList<>(checks.keySet()),checks,512,256,16,WORK,4096);require(units.collection.collected&&compounds.collection.collected,units.collection.reason+compounds.collection.reason);
        ContextUniversalSignedUnitExchange.SessionRebase u=ContextUniversalSignedUnitExchange.rebaseWithValidationReuse(units.collection.output,first,WORK,4096);ContextUniversalCompoundExchange.SessionRebase c=ContextUniversalCompoundExchange.rebaseWithValidationReuse(compounds.collection.output,first,WORK,4096);ContextUniversalFrozenConstraints.SessionClosure replay=ContextUniversalFrozenConstraints.closeSignedCompoundsWithValidationReuse(ContextUniversalCompoundExchangeRunner.rows(f.x,f.e),first.packet,null,u.exchange,c.exchange,16,16,512,256,WORK,4096);require(replay.result.closed&&replay.result.xRefuted&&replay.metrics.entries==0&&replay.metrics.verified>0,replay.result.reason);List<Support> empty=new ArrayList<>();for(org.kanger.ContextUniversalFrozenConstraints.Proof p:replay.result.proofs)if(p.clause==null)empty.add(p.support);require(ContextUniversalSourceAlternativesMatrix.supports(empty).equals(f.early()),"FRESH ordinary semantic replay independently reconstructs all three exact empty Source-grade alternatives");
    }
    static void delayedPartition(int first)throws Exception {Fixture f=new Fixture(false);List<Snapshot> cuts=Arrays.asList(f.a,f.b,f.d,f.e);List<List<Snapshot>> orders=ContextUniversalContinuationRefutationRunner.permutations(cuts);require(orders.size()==24&&new HashSet<>(orders).size()==24,"ALL twenty-four independent four-cut orders enumerated");Map<Cut,Set<Support>> previous=null;int count=0;for(List<Snapshot> order:orders)if(order.get(0)==cuts.get(first)){Frame frame=f.frame(order);Result r=rejection(f,frame,false);Map<Cut,Set<Support>> evidence=ContextUniversalPrivateSymbolicMatrix.evidence(r);if(previous!=null)require(previous.equals(evidence),"complete earliest per-cut Source/grade evidence invariant under enumeration");previous=evidence;if(count++==0){ordinaryReplay(f,frame);SessionRun limit=run(frame,1,WORK,4096);incomplete(limit,"progress before NEXT negative qualification cannot publish stable prefix");noStableAudit(frame,limit);}}require(count==6,"six orders in isolated first-cut partition");System.out.println("SIGNED_ALTERNATIVES_DELAYED first="+first+" orders=6 rejectionBarrier=2 exactEmptyAlternatives=3 freshOrdinaryReplay=1");}
    static void trustedRejection()throws Exception {Fixture f=new Fixture(false);Map<Object,Set<Support>> previous=null;int count=0;Frame last=null;for(List<Snapshot> members:ContextUniversalContinuationRefutationRunner.permutations(Arrays.asList(f.b,f.d,f.e))){Snapshot group=ContextProductionNativeBinding.trusted("signed-boundary",members,WORK);require(Cut.of(group).members.size()==3,"all three actual rule/donor/negative members retained");for(List<Snapshot> order:Arrays.asList(Arrays.asList(f.a,group),Arrays.asList(group,f.a))){Frame frame=f.frame(order);Result r=rejection(f,frame,true);Map<Object,Set<Support>> evidence=ContextUniversalSeparatePrivateMatrix.physicalEvidence(ContextUniversalPrivateSymbolicMatrix.evidence(r));if(previous!=null)require(previous.equals(evidence),"complete physical-member Source/grade rejection inventory invariant under all member/cut orders");previous=evidence;++count;if(order.get(0)==group)last=frame;}}
        require(count==12,"ALL six member permutations and two cut orders");SessionRun missing=ContextUniversalGroupedRounds.runWithValidationReuse(f.x,last.cuts,f.common,Collections.emptyMap(),last.units,last.compounds,last.limits,last.local,8,WORK,4096);incomplete(missing,"later missing private pool suppresses earlier real trusted sixteen-alternative contradiction");require(missing.result.phase.equals("checks")&&missing.result.reason.contains("Missing actual full original witness row"),"all-cut verification before ANY rejection export");noStableAudit(last,missing);System.out.println("SIGNED_ALTERNATIVES_TRUSTED_REJECTION memberOrders=6 cutOrders=2 rejectionBarrier=1 exactEmptyAlternativesPerCut=16 laterMissingPrivateAtomic=true");}
}
